"""
Format Grammar Validator for AutoVideoPipeline.
Strictly enforces the canonical Five Formats (F1-F5) source grammar and failure matrix.
Raises FORMAT_GRAMMAR_VIOLATION on any source class or structure breach.
"""
from pathlib import Path
from typing import List, Dict, Any, Optional
from .models import FormatId, SourceClass, FormatPlan, VisualSegment, LayoutProfile


class FORMAT_GRAMMAR_VIOLATION(ValueError):
    """Raised when timeline composition violates the bound format's product contract."""
    pass


class FormatValidator:
    """
    Validates that a timeline schedule complies with the selected FormatPlan
    prior to Stage 3 finalization and Stage 4 rendering.
    """

    @staticmethod
    def validate_timeline(segments: List[VisualSegment], format_plan: FormatPlan, *, require_files: bool = False) -> Dict[str, Any]:
        """
        Validates the visual segments against the FormatPlan grammar.
        Raises FORMAT_GRAMMAR_VIOLATION on any breach.
        """
        if not segments:
            raise FORMAT_GRAMMAR_VIOLATION("Timeline is empty. Full visual coverage is required.")

        if require_files:
            for seg in segments:
                path = Path(seg.source_path)
                if not path.is_file() or path.stat().st_size == 0:
                    raise FORMAT_GRAMMAR_VIOLATION(
                        f"Required media is missing or empty at segment {seg.index}: {path}"
                    )

        fmt = format_plan.format_id

        # Normalize segment source class mapping
        for seg in segments:
            if not seg.source_class:
                seg.source_class = FormatValidator._infer_source_class(seg)

        if fmt == FormatId.F1:
            return FormatValidator._validate_f1(segments, format_plan)
        elif fmt == FormatId.F2:
            return FormatValidator._validate_f2(segments, format_plan)
        elif fmt == FormatId.F3:
            return FormatValidator._validate_f3(segments, format_plan)
        elif fmt == FormatId.F4:
            return FormatValidator._validate_f4(segments, format_plan)
        elif fmt == FormatId.F5:
            return FormatValidator._validate_f5(segments, format_plan)
        else:
            raise FORMAT_GRAMMAR_VIOLATION(f"Unsupported format: {fmt}")

    @staticmethod
    def _infer_source_class(seg: VisualSegment) -> SourceClass:
        t = seg.segment_type.lower()
        if t in ("chap1_opening", "veo_opening", "veo_ai", "veo"):
            return SourceClass.GENERATED_VIDEO
        elif t in ("slideshow", "image", "f1_fullscreen"):
            return SourceClass.GENERATED_IMAGE
        elif t in ("stock", "stock_opening"):
            return SourceClass.STOCK_ONLINE
        elif t in ("f1_framed", "reup", "original_source"):
            return SourceClass.ORIGINAL_REUP_VIDEO
        return SourceClass.STOCK_ONLINE

    @staticmethod
    def _validate_f1(segments: List[VisualSegment], plan: FormatPlan) -> Dict[str, Any]:
        """
        F1: AI Opening (Veo) + AI Images (Flow).
        Stock video is strictly forbidden in normal F1 semantics.
        """
        opening_segs = [s for s in segments if s.segment_type in ("chap1_opening", "veo_opening")]
        if not opening_segs:
            # Fallback to first segment as opening
            opening_segs = [segments[0]]
            body_segs = segments[1:]
        else:
            body_segs = [s for s in segments if s not in opening_segs]

        for s in opening_segs:
            if s.source_class != SourceClass.GENERATED_VIDEO:
                raise FORMAT_GRAMMAR_VIOLATION(
                    f"F1 requires AI Opening video (GENERATED_VIDEO), found: {s.source_class.value}"
                )

        if not body_segs:
            raise FORMAT_GRAMMAR_VIOLATION("F1 timeline contains no body segments.")

        for seg in body_segs:
            if seg.source_class == SourceClass.STOCK_ONLINE:
                raise FORMAT_GRAMMAR_VIOLATION(
                    f"F1 rejects STOCK_ONLINE in main program at segment {seg.index}: {seg.description}"
                )
            if seg.source_class != SourceClass.GENERATED_IMAGE:
                raise FORMAT_GRAMMAR_VIOLATION(
                    f"F1 requires GENERATED_IMAGE in main program, found: {seg.source_class.value} at segment {seg.index}"
                )

        return {"valid": True, "format": "F1", "segments_count": len(segments)}

    @staticmethod
    def _validate_f2(segments: List[VisualSegment], plan: FormatPlan) -> Dict[str, Any]:
        """
        F2: AI Opening + Stock + AI Video.
        post_opening_mix_semantics = BOTH_CLASSES_REQUIRED.
        Timeline must contain >= 1 intentional STOCK_ONLINE interval
        AND >= 1 intentional post-opening GENERATED_VIDEO interval.
        """
        opening_seg = segments[0]
        if opening_seg.source_class != SourceClass.GENERATED_VIDEO:
            raise FORMAT_GRAMMAR_VIOLATION(
                f"F2 requires AI Opening video (GENERATED_VIDEO), found: {opening_seg.source_class.value}"
            )

        post_opening = segments[1:]
        if not post_opening:
            raise FORMAT_GRAMMAR_VIOLATION("F2 timeline contains no post-opening segments.")

        stock_count = 0
        ai_video_count = 0

        for seg in post_opening:
            if seg.source_class == SourceClass.STOCK_ONLINE:
                stock_count += 1
            elif seg.source_class == SourceClass.GENERATED_VIDEO:
                ai_video_count += 1
            else:
                raise FORMAT_GRAMMAR_VIOLATION(
                    f"F2 post-opening forbids {seg.source_class.value} at segment {seg.index}. Allowed: {{STOCK_ONLINE, GENERATED_VIDEO}}"
                )

        if stock_count < 1:
            raise FORMAT_GRAMMAR_VIOLATION(
                "F2 requires at least 1 intentional STOCK_ONLINE interval (BOTH_CLASSES_REQUIRED). Found 0."
            )
        if ai_video_count < 1:
            raise FORMAT_GRAMMAR_VIOLATION(
                "F2 requires at least 1 intentional post-opening GENERATED_VIDEO interval (BOTH_CLASSES_REQUIRED). Found 0."
            )

        return {
            "valid": True,
            "format": "F2",
            "stock_intervals": stock_count,
            "ai_video_intervals": ai_video_count
        }

    @staticmethod
    def _validate_f3(segments: List[VisualSegment], plan: FormatPlan) -> Dict[str, Any]:
        """
        F3: Full AI Images.
        Zero stock video, zero AI video opening.
        """
        for seg in segments:
            if seg.source_class in (SourceClass.STOCK_ONLINE, SourceClass.GENERATED_VIDEO, SourceClass.ORIGINAL_REUP_VIDEO):
                raise FORMAT_GRAMMAR_VIOLATION(
                    f"F3 requires 100% GENERATED_IMAGE. Found forbidden {seg.source_class.value} at segment {seg.index}"
                )

        return {"valid": True, "format": "F3", "segments_count": len(segments)}

    @staticmethod
    def _validate_f4(segments: List[VisualSegment], plan: FormatPlan) -> Dict[str, Any]:
        """
        F4: Reup.
        Online background video + original source video displayed smaller/inset.
        LayoutProfile must not obscure source video or hide background.
        """
        layout: Optional[LayoutProfile] = plan.layout_profile
        if not layout:
            raise FORMAT_GRAMMAR_VIOLATION("F4 Reup requires a bound LayoutProfile.")

        if layout.foreground_scale >= 1.0 or layout.foreground_scale <= 0.1:
            raise FORMAT_GRAMMAR_VIOLATION(
                f"F4 LayoutProfile geometry invalid: foreground_scale={layout.foreground_scale}. Must be between 0.1 and 0.95."
            )

        has_original = any(seg.source_class == SourceClass.ORIGINAL_REUP_VIDEO for seg in segments)
        if not has_original:
            raise FORMAT_GRAMMAR_VIOLATION("F4 Reup requires an ORIGINAL_REUP_VIDEO source file.")
        if not any(seg.source_class == SourceClass.STOCK_ONLINE for seg in segments):
            raise FORMAT_GRAMMAR_VIOLATION("F4 Reup requires a STOCK_ONLINE background source.")
        if any(seg.source_class not in (SourceClass.ORIGINAL_REUP_VIDEO, SourceClass.STOCK_ONLINE) for seg in segments):
            raise FORMAT_GRAMMAR_VIOLATION("F4 allows only ORIGINAL_REUP_VIDEO and STOCK_ONLINE sources.")

        return {"valid": True, "format": "F4", "layout_id": layout.layout_id}

    @staticmethod
    def _validate_f5(segments: List[VisualSegment], plan: FormatPlan) -> Dict[str, Any]:
        """
        F5: Full Custom Video.
        100% STOCK_ONLINE footage for the full visual program.
        Zero Flow images, zero Flow video, zero arbitrary local media.
        """
        for seg in segments:
            if seg.source_class != SourceClass.STOCK_ONLINE:
                raise FORMAT_GRAMMAR_VIOLATION(
                    f"F5 rejects {seg.source_class.value} at segment {seg.index}. Allowed: STOCK_ONLINE only."
                )

        return {"valid": True, "format": "F5", "stock_segments": len(segments)}

    @staticmethod
    def handle_source_failure(
        format_id: FormatId,
        failure_phase: str,  # "opening", "main_stock", "main_ai_video", "main_ai_image", "background"
        attempts: int,
        max_attempts: int = 2,
        current_stock_count: int = 0
    ) -> Dict[str, Any]:
        """
        Implements the canonical required-source failure matrix.
        Never mutates format identity in place.
        """
        if attempts < max_attempts:
            return {
                "disposition": "RETRY_SAME_SOURCE",
                "message": f"Bounded retry attempt {attempts + 1}/{max_attempts} for {failure_phase}"
            }

        # Exhausted retries
        if format_id == FormatId.F2 and failure_phase == "main_stock":
            # F2 stock interval NO_MATCH can route to GENERATED_VIDEO only if
            # the remaining timeline still has >= 1 stock interval and remains F2 compliant
            if current_stock_count > 1:
                return {
                    "disposition": "ROUTE_TO_GENERATED_VIDEO",
                    "message": "Routing single stock interval to GENERATED_VIDEO while preserving F2 BOTH_CLASSES_REQUIRED"
                }

        # All other failure states must escalate without silent format mutation
        return {
            "disposition": "NEEDS_OWNER_OR_FAIL",
            "message": f"Source failure in {format_id.value} during {failure_phase}. Escalated to owner."
        }

"""Recheck byte-bound evidence emitted by a completed local render."""
import hashlib
import json
import subprocess
from pathlib import Path
from typing import Any, Dict, List


def _frame_rgb(path: Path, seconds: float) -> bytes:
    result = subprocess.run(
        ["ffmpeg", "-v", "error", "-ss", f"{max(0, seconds):.3f}", "-i", str(path),
         "-frames:v", "1", "-vf", "scale=32:18:force_original_aspect_ratio=decrease,pad=32:18:(ow-iw)/2:(oh-ih)/2",
         "-f", "rawvideo", "-pix_fmt", "rgb24", "-"],
        capture_output=True, check=False,
    )
    if result.returncode or len(result.stdout) != 32 * 18 * 3:
        raise ValueError(f"Could not decode verification frame from {path}")
    return result.stdout


def _region_mean(frame: bytes, region: str) -> List[float]:
    # Coarse color signatures are robust to codec noise and catch wrong-source renders.
    coords = {
        "all": (0, 0, 32, 18), "center": (8, 4, 24, 14),
        "corner": (0, 0, 6, 6),
    }[region]
    x0, y0, x1, y1 = coords
    pixels = [frame[(y * 32 + x) * 3:(y * 32 + x) * 3 + 3]
              for y in range(y0, y1) for x in range(x0, x1)]
    return [sum(pixel[channel] for pixel in pixels) / len(pixels) for channel in range(3)]


def _matches_source(source: Path, output: Path, source_time: float, output_time: float,
                    source_region: str = "all", output_region: str = "all") -> Dict[str, Any]:
    expected = _region_mean(_frame_rgb(source, source_time), source_region)
    observed = _region_mean(_frame_rgb(output, output_time), output_region)
    error = sum(abs(a - b) for a, b in zip(expected, observed)) / 3
    return {"source": str(source), "source_rgb_mean": expected, "output_rgb_mean": observed,
            "mean_absolute_error": error, "passed": error <= 45}


def verify_visual_evidence(data: Dict[str, Any]) -> List[str]:
    """Decode output frames and check their visual signatures against each declared source."""
    output = Path(data.get("output_file", ""))
    schedule = data.get("product_state", {}).get("timeline_state", {})
    segments = schedule.get("segments", [])
    fmt = data.get("format_id")
    failures: List[str] = []
    if not output.is_file() or not segments:
        return ["visual evidence lacks output or timeline segments"]
    checks = []
    offset = 0.0
    for segment in segments:
        duration = float(segment.get("duration", 0))
        source = Path(segment.get("source_path") or segment.get("source", ""))
        source_class = segment.get("source_class", "")
        segment_type = segment.get("segment_type") or segment.get("type", "")
        sample_out = (max(0.05, duration * 0.5) if fmt == "F4"
                      else offset + max(0.05, duration * 0.5))
        source_time = (0.0 if source.suffix.lower() in {".jpg", ".jpeg", ".png", ".webp", ".bmp"}
                       else float(segment.get("start_time", segment.get("start", 0))) + max(0.05, duration * 0.5))
        if fmt == "F4" and segment_type == "f1_framed":
            # F4's original is the inset, while the separately declared stock asset is its canvas.
            checks.append(_matches_source(source, output, source_time, sample_out, "center", "center"))
            bg = next((Path(s.get("source_path") or s.get("source")) for s in segments
                       if s.get("source_class") == "STOCK_ONLINE" and (s.get("source_path") or s.get("source"))), None)
            if bg is None:
                failures.append("F4 background source missing from evidence")
            else:
                checks.append(_matches_source(bg, output, duration * 0.5, sample_out, "all", "corner"))
        elif fmt == "F4":
            # Background is composited beneath the inset; it is not a concat segment.
            offset += duration
            continue
        else:
            checks.append(_matches_source(source, output, source_time, sample_out))
        offset += duration
    for index, check in enumerate(checks):
        if not check["passed"]:
            failures.append(f"decoded source comparison {index} failed (MAE {check['mean_absolute_error']:.1f})")
    data.setdefault("product_state", {})["visual_evidence"] = checks
    return failures


def _file_hash(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def verify_run_manifest(manifest_path: Path) -> Dict[str, Any]:
    """Return valid only while all bound assets, state files, code, and output match."""
    manifest_path = Path(manifest_path)
    data = json.loads(manifest_path.read_text(encoding="utf-8"))
    failures: List[str] = []
    if data.get("accepted") is not True:
        failures.append("run is not marked accepted")

    def check(path_text: str, expected: str, label: str) -> None:
        path = Path(path_text) if path_text else None
        if not path or not path.is_file():
            failures.append(f"{label} missing: {path_text}")
        elif not expected or _file_hash(path) != expected:
            failures.append(f"{label} hash mismatch: {path_text}")

    check(data.get("output_file", ""), data.get("output_sha256", ""), "output")
    if data.get("format_id") not in {"F1", "F2", "F3", "F4", "F5"}:
        failures.append("unsupported or missing selected format")
    for asset in data.get("assets_used", []):
        check(asset.get("source_path", ""), asset.get("sha256", ""), f"asset {asset.get('index')}")
    state = data.get("product_state", {})
    try:
        from .format_validator import FormatValidator
        from .models import FormatId, create_default_format_plan
        selected = FormatId(data.get("format_id", ""))
        timeline = state.get("timeline_state", {})
        if timeline.get("format_id") != selected.value:
            failures.append("selected format does not match timeline format")
        segments = timeline.get("segments", [])
        from .models import VisualSegment, SourceClass
        rebuilt = [VisualSegment(
            index=s["index"], start_time=s.get("start_time", s.get("start", 0)), duration=s["duration"],
            segment_type=s.get("segment_type", s.get("type", "")), source_path=Path(s.get("source_path") or s.get("source", "")),
            source_class=SourceClass(s["source_class"]) if s.get("source_class") else None,
            asset_id=s.get("asset_id", ""), description=s.get("description", ""))
            for s in segments]
        FormatValidator.validate_timeline(rebuilt, create_default_format_plan(selected), require_files=True)
    except Exception as exc:
        failures.append(f"format/source validation failed: {exc}")
    canonical_timeline = json.dumps(state.get("timeline_state"), sort_keys=True, ensure_ascii=False, default=str).encode("utf-8")
    if hashlib.sha256(canonical_timeline).hexdigest() != state.get("timeline_sha256"):
        failures.append("timeline state hash mismatch")
    check(state.get("compose_path", ""), state.get("compose_sha256", ""), "compose state")
    check(state.get("audio_path", ""), state.get("audio_sha256", ""), "audio")
    if state.get("timeline_file_sha256"):
        check(state.get("timeline_path", ""), state["timeline_file_sha256"], "timeline state")
    if not state.get("visual_evidence"):
        failures.append("decoded visual evidence missing")
    else:
        try:
            failures.extend(verify_visual_evidence(data))
        except Exception as exc:
            failures.append(f"decoded visual verification failed: {exc}")
    package = Path(__file__).resolve().parent
    digest = hashlib.sha256()
    for source in sorted(package.rglob("*.py")):
        digest.update(source.relative_to(package).as_posix().encode("utf-8"))
        digest.update(_file_hash(source).encode("ascii"))
    if digest.hexdigest() != state.get("candidate_sha256"):
        failures.append("candidate code hash mismatch")
    return {"valid": not failures, "failures": failures, "format_id": data.get("format_id"),
            "output_file": data.get("output_file"), "output_sha256": data.get("output_sha256")}

"""
Pre-persistence secret redaction module for AutoVideoPipeline.
Guarantees that credentials, API keys, auth tokens, and session cookies
are never written to manifests, logs, test artifacts, or exported data.
"""
import os
import re
from pathlib import Path
from typing import Any, Dict, List, Set, Union

REDACTED_PLACEHOLDER = "[REDACTED]"

# Regex patterns matching common secret formats
AUTH_HEADER_REGEX = re.compile(r"(Bearer\s+)[A-Za-z0-9_\-\.]{10,}", re.IGNORECASE)
GENERIC_API_KEY_REGEX = re.compile(r"(?i)(api[_\-]?key|token|secret|password|auth|cookie|authorization)[\"']?\s*[:=]\s*[\"']([^\"']{6,})[\"']")
COOKIE_TOKEN_REGEX = re.compile(r"(?i)(SID|HSID|SSID|__Secure-[\w\-]+|session_id)=([A-Za-z0-9_\-\.]{8,})")
GEMINI_KEY_REGEX = re.compile(r"AIzaSy[A-Za-z0-9_\-]{33}")
PEXELS_KEY_REGEX = re.compile(r"[a-f0-9]{56}", re.IGNORECASE)

_REGISTERED_SECRETS: Set[str] = set()


def register_secret_value(value: str) -> None:
    """Registers a sensitive string to ensure it is always redacted."""
    if value and len(value.strip()) >= 5:
        _REGISTERED_SECRETS.add(value.strip())


def load_and_register_disk_secrets(api_keys_dir: Path) -> None:
    """Reads all key and cookie files from disk to populate the redaction blacklist."""
    if not api_keys_dir.exists():
        return
    for item in api_keys_dir.glob("*.txt"):
        try:
            content = item.read_text(encoding="utf-8").strip()
            if content:
                for line in content.splitlines():
                    clean = line.strip()
                    if len(clean) >= 6:
                        register_secret_value(clean)
        except Exception:
            pass


def redact_string(text: str) -> str:
    """Scrubs all sensitive tokens and patterns from a string."""
    if not text:
        return text

    redacted = text

    # Exact registered secret blacklist
    for sec in _REGISTERED_SECRETS:
        if sec in redacted:
            redacted = redacted.replace(sec, REDACTED_PLACEHOLDER)

    # Patterns
    redacted = AUTH_HEADER_REGEX.sub(r"\1" + REDACTED_PLACEHOLDER, redacted)
    redacted = GEMINI_KEY_REGEX.sub(REDACTED_PLACEHOLDER, redacted)
    redacted = COOKIE_TOKEN_REGEX.sub(r"\1=" + REDACTED_PLACEHOLDER, redacted)
    redacted = GENERIC_API_KEY_REGEX.sub(r'\1: "' + REDACTED_PLACEHOLDER + '"', redacted)

    return redacted


def redact_data(data: Any) -> Any:
    """
    Recursively scrubs dictionary, list, and string structures before serialization.
    """
    if isinstance(data, str):
        return redact_string(data)
    elif isinstance(data, dict):
        cleaned: Dict[str, Any] = {}
        for k, v in data.items():
            k_lower = str(k).lower()
            if any(term in k_lower for term in ("cookie", "api_key", "secret", "token", "password", "auth", "credential")):
                cleaned[k] = REDACTED_PLACEHOLDER
            else:
                cleaned[k] = redact_data(v)
        return cleaned
    elif isinstance(data, list):
        return [redact_data(item) for item in data]
    elif isinstance(data, tuple):
        return tuple(redact_data(item) for item in data)
    return data


def sanitize_cmd_args(args: List[str]) -> List[str]:
    """Sanitizes command line argument lists to prevent credential leakage in logs/argv."""
    sanitized: List[str] = []
    for arg in args:
        sanitized.append(redact_string(arg))
    return sanitized
